import React from 'react';
import './AudienceSection.css';

const AudienceSection = () => {
    const audiencePoints = [
        'Выбирает места для гастрономических впечатлений на основе проверенных данных, а не случайных рекомендаций',
        'Рассматривает рестораны как пространство для деловых и личных событий, где важен гарантированный уровень качества',
        'Ценит профессиональную экспертизу выше субъективных впечатлений'
    ];

    return (
        <section className="audience-section">
            <div className="audience-container">
                <div className="audience-content">
                    <h2 className="section-title">Наша аудитория</h2>
                    <p className="audience-description">
                        Мы создаём сервис для тех, кто:
                    </p>
                    <ul className="audience-list">
                        {audiencePoints.map((point, index) => (
                            <li key={index} className="audience-item">
                                <span className="bullet"></span>
                                <span>{point}</span>
                            </li>
                        ))}
                    </ul>
                </div>
                <div className="audience-image">
                    <img 
                        src="/assets/images/audience.jpg" 
                        alt="Наша аудитория"
                        onError={(e) => {
                            e.target.src = '/assets/images/venue.jpg';
                            e.target.onerror = null;
                        }}
                    />
                </div>
            </div>
        </section>
    );
};

export default AudienceSection;
